user_html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SP WorldTech — Client Dashboard</title><link rel="icon" href="./assets/favicon.jpeg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="./assets/role-dashboards.css"><link rel="stylesheet" href="./assets/comments.css"><script defer src="./assets/app-config.js"></script><script src="https://unpkg.com/lucide@latest"></script></head><body><div class="workspace"><aside class="side"><div class="side-brand"><img src="./assets/logo.jpeg" alt="SP WorldTech"><strong>SP WorldTech</strong><span>Client Workspace</span></div><nav class="side-nav"><button class="active" data-go="overview">◈ Overview</button><button data-go="projects">▣ My Projects</button><button data-go="marketplace">◇ Marketplace</button><button data-go="payments">$ Payments</button><button data-go="academy">◎ Academy</button><button data-go="support">✦ Support</button><button data-go="profile">◯ Profile</button></nav><div class="side-bottom"><div class="role-chip">Authenticated role</div><div style="font-size:11px;margin-top:5px">Client / User</div><a class="ad" href="https://worldnethosting.com" target="_blank" rel="noopener" style="margin-top:14px"><b>World Net Hosting</b><span>Professional domains and hosting for your online presence.</span></a><button class="logout" id="logout">Sign out</button></div></aside><main class="main"><header class="top"><div><h1>Client Dashboard</h1><p>Manage your projects, purchases, payments and support in one place.</p></div><div class="top-user"><div class="avatar" id="avatar">U</div><div><strong id="userName">Client</strong><span>Verified account</span></div></div></header><div class="content"><section class="section active" id="overview"><div class="hero"><div><h2>Welcome back, <span id="welcome">Client</span></h2><p>Your SP WorldTech workspace is ready. Continue a project, explore digital products or contact support.</p></div><div class="hero-actions"><a class="btn" href="./projects.html">Request a Project</a><a class="btn" href="./marketplace.html">Browse Marketplace</a></div></div><div class="grid4"><div class="stat"><small>Wallet</small><strong id="wallet">$0.00</strong><span>Available balance</span></div><div class="stat"><small>Projects</small><strong id="projectCount">0</strong><span>Active and completed</span></div><div class="stat"><small>Purchases</small><strong id="purchaseCount">0</strong><span>Digital products</span></div><div class="stat"><small>Support</small><strong id="messageCount">0</strong><span>Recent messages</span></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h3>Recent Projects</h3><button class="btn" data-go="projects">View all</button></div><div id="recentProjects" class="list"><div class="empty">Loading projects…</div></div></div><div><div class="panel"><h3>Quick actions</h3><div class="cards"><div class="mini"><strong>Pay Project</strong><p>Continue a full or half payment.</p></div><div class="mini"><strong>Download</strong><p>Access purchased products.</p></div><div class="mini"><strong>Support</strong><p>Message the SP WorldTech team.</p></div></div></div><a class="ad" href="https://worldnethosting.com" target="_blank" rel="noopener"><b>World Net Hosting</b><span>Domains • Hosting • Online business infrastructure</span></a></div></div></section><section class="section" id="projects"><div class="panel"><div class="panel-head"><h3>My Projects & Delivery</h3><a class="btn" href="./contact.html">New project request</a></div><div id="projectsList" class="list"><div class="empty">Loading…</div></div></div></section><section class="section" id="marketplace"><div class="panel"><div class="panel-head"><h3>Live Marketplace</h3><a class="btn" href="./marketplace.html">Open Marketplace</a></div><div id="products" class="product-grid"><div class="empty">Loading live products…</div></div></div></section><section class="section" id="payments"><div class="panel"><h3>Payments & Wallet</h3><div class="notice">Payments are processed through the current SP WorldTech payment workflow. Never share your PIN, OTP or password.</div><div class="grid4"><div class="stat"><small>USD Balance</small><strong id="walletUsd">$0.00</strong></div><div class="stat"><small>NGN Balance</small><strong id="walletNgn">₦0</strong></div><div class="stat"><small>Visible Earnings</small><strong id="earnings">$0.00</strong></div><div class="stat"><small>Payment Status</small><strong>Secure</strong></div></div></div></section><section class="section" id="academy"><div class="panel"><div class="panel-head"><h3>AI Coding Academy</h3><a class="btn" href="./academy.html">Open Academy</a></div><div class="cards"><div class="mini"><strong>Learn</strong><p>Build practical software development skills.</p></div><div class="mini"><strong>Practice</strong><p>Use the coding and AI learning workflows.</p></div><div class="mini"><strong>Progress</strong><p>Continue your learning journey from the Academy.</p></div></div></div></section><section class="section" id="support"><div class="panel"><h3>Support</h3><div id="messages" class="list"><div class="empty">Loading support messages…</div></div><form id="supportForm" class="support-box" style="margin-top:12px"><textarea id="message" placeholder="Write your support message..."></textarea><button class="btn primary">Send</button></form></div></section><section class="section" id="profile"><div class="panel"><h3>My Profile</h3><div class="grid2"><div class="mini"><strong id="profileName">Client</strong><p id="profileEmail">—</p><p>Role: User / Client</p></div><div class="mini"><strong>Account security</strong><p>Your authenticated session is protected by the current SP WorldTech API and role controls.</p></div></div></div></section></div></main></div><div class="toast" id="toast"></div><script>const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];const token=localStorage.getItem('spw_user_token');if(!token)location.replace('./auth.html?next=./dashboard.html');const user=JSON.parse(localStorage.getItem('spw_user')||'{}');const api=(p,o={})=>window.SPW_APP.api(p,o);function show(id){$$('.section').forEach(x=>x.classList.toggle('active',x.id===id));$$('[data-go]').forEach(x=>x.classList.toggle('active',x.dataset.go===id));location.hash=id}$$('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));$('#logout').onclick=()=>{localStorage.removeItem('spw_user_token');localStorage.removeItem('spw_user');location.replace('./auth.html')};const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n||0));function fillUser(){const name=user.fullName||user.name||'Client';$('#welcome').textContent=name.split(' ')[0];$('#userName').textContent=name;$('#profileName').textContent=name;$('#profileEmail').textContent=user.email||'—';$('#avatar').textContent=name[0]?.toUpperCase()||'U'}async function load(){try{const [w,p,bu,m]=await Promise.all([api('/api/wallet/me'),api('/api/project/me'),api('/api/marketplace/purchases'),api('/api/chat/me')]);const wallet=w.wallet||{};$('#wallet').textContent=money(wallet.usdBalance);$('#walletUsd').textContent=money(wallet.usdBalance);$('#walletNgn').textContent='₦'+Number(wallet.ngnBalance||0).toLocaleString();$('#earnings').textContent=money(wallet.visibleEarnings);const projects=p.projects||[];$('#projectCount').textContent=projects.length;$('#purchaseCount').textContent=(bu.purchases||[]).length;$('#messageCount').textContent=(m.messages||[]).length;renderProjects(projects);renderMessages(m.messages||[])}catch(e){console.warn(e);}}function renderProjects(items){const html=items.slice(0,8).map(x=>`<div class="list-item"><div class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.description||'Project')} • ${esc(x.status||'pending')}</small></div><span class="badge">${money(x.paidAmount)} paid</span></div>`).join('')||'<div class="empty">No projects yet. Contact SP WorldTech to start one.</div>';$('#recentProjects').innerHTML=html;$('#projectsList').innerHTML=items.map(x=>`<div class="list-item"><div class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.clientEmail||user.email||'')} • ${esc(x.status||'pending')}</small></div><span class="badge">${money(x.remainingAmount)} remaining</span></div>`).join('')||'<div class="empty">No projects yet.</div>'}async function loadProducts(){try{const d=await api('/api/marketplace/ebooks');const items=d.ebooks||[];$('#products').innerHTML=items.map(x=>{const price=Number(x.price||0),old=Number(x.oldPrice||0);return `<article class="product"><h4>${esc(x.title)}</h4><p>${esc(x.description||x.category||'Digital product')}</p><div>${old>price?`<span class="old">$${old.toFixed(2)}</span>`:''}${price<=0?'<span class="free">Download Free</span>`':`<span class="price">$${price.toFixed(2)}</span>`}</div><div class="actions"><a class="btn" href="./marketplace.html?buy=${encodeURIComponent(x.id)}">${price<=0?'Open':'Buy Now'}</a></div></article>`}).join('')||'<div class="empty">No live products are published yet.</div>'}catch(e){$('#products').innerHTML='<div class="empty">Marketplace is temporarily unavailable.</div>'}}async function loadMessages(){try{const d=await api('/api/chat/me');renderMessages(d.messages||[])}catch(e){}}function renderMessages(items){$('#messages').innerHTML=items.slice(-15).map(x=>`<div class="list-item"><div class="grow"><strong>${esc(x.senderRole||'Support')}</strong><small>${esc(x.message||'')}</small></div></div>`).join('')||'<div class="empty">No support messages yet.</div>'}$('#supportForm').onsubmit=async e=>{e.preventDefault();const message=$('#message').value.trim();if(!message)return;try{await api('/api/chat/send',{method:'POST',body:JSON.stringify({message})});$('#message').value='';toast('Message sent to support.');loadMessages()}catch(err){toast(err.message)}};function toast(x){const t=$('#toast');t.textContent=x;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}fillUser();load();loadProducts();if(location.hash)show(location.hash.slice(1));</script></body></html>'''

