admin_html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SP WorldTech — Admin Control Center</title><link rel="icon" href="./assets/favicon.jpeg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="./assets/role-dashboards.css"><script defer src="./assets/app-config.js"></script></head><body><div class="workspace"><aside class="side"><div class="side-brand"><img src="./assets/logo.jpeg" alt="SP WorldTech"><strong>SP WorldTech</strong><span>Admin Control Center</span></div><nav class="side-nav"><button class="active" data-go="overview">◈ Overview</button><button data-go="users">♙ Users</button><button data-go="jobs">▣ Jobs & Applications</button><button data-go="projects">◆ Projects</button><button data-go="marketplace">◇ Marketplace</button><button data-go="messages">✦ Support</button><button data-go="settings">⚙ Platform</button></nav><div class="side-bottom"><div class="role-chip">Authenticated role</div><div style="font-size:11px;margin-top:5px">Admin / Owner</div><a class="ad" href="https://worldnethosting.com" target="_blank" rel="noopener" style="margin-top:14px"><b>World Net Hosting</b><span>Keep the hosting promotion visible without mixing it with administration.</span></a><button class="logout" id="logout">Sign out</button></div></aside><main class="main"><header class="top"><div><h1>Admin Control Center</h1><p>Manage platform operations, projects, jobs, marketplace and support.</p></div><div class="top-user"><div class="avatar">A</div><div><strong id="adminName">Administrator</strong><span>Protected admin workspace</span></div></div></header><div class="content"><section class="section active" id="overview"><div class="hero"><div><h2>Platform control, rebuilt.</h2><p>This dashboard is a clean role-based workspace. Financial and operational data stays inside the authenticated admin area.</p></div><div class="hero-actions"><button class="btn" data-go="projects">Projects</button><button class="btn" data-go="marketplace">Marketplace</button></div></div><div class="grid4"><div class="stat"><small>Users</small><strong id="users">0</strong><span>Registered clients</span></div><div class="stat"><small>Jobs</small><strong id="jobs">0</strong><span>Job records</span></div><div class="stat"><small>Applications</small><strong id="apps">0</strong><span>Recent applications</span></div><div class="stat"><small>Pending withdrawals</small><strong id="withdrawals">0</strong><span>Awaiting admin action</span></div></div><div class="grid2"><div class="panel"><div class="panel-head"><h3>Recent Applications</h3><button class="btn" data-go="jobs">Manage</button></div><div id="recentApps" class="list"><div class="empty">Loading…</div></div></div><div class="panel"><h3>Admin responsibilities</h3><div class="list"><div class="list-item"><div class="grow"><strong>Client delivery</strong><small>Track projects, payment status and delivery.</small></div></div><div class="list-item"><div class="grow"><strong>Marketplace</strong><small>Publish, edit or remove live products.</small></div></div><div class="list-item"><div class="grow"><strong>Operations</strong><small>Review jobs, applications and support activity.</small></div></div></div></div></div></section><section class="section" id="users"><div class="panel"><h3>Users & activity</h3><div class="notice">The API intentionally returns operational records according to the current authenticated admin role.</div><div id="usersList" class="list"><div class="empty">Loading…</div></div></div></section><section class="section" id="jobs"><div class="panel"><div class="panel-head"><h3>Jobs & Applications</h3><button class="btn" onclick="loadDashboard()">Refresh</button></div><div id="jobsList" class="list"><div class="empty">Loading…</div></div></div></section><section class="section" id="projects"><div class="panel"><div class="panel-head"><h3>Project Delivery</h3><button class="btn" onclick="showCreateProject()">Create project</button></div><div id="projectList" class="list"><div class="empty">Loading…</div></div><div id="createProject" style="display:none;margin-top:15px"><form id="projectForm" class="form-grid"><div class="field"><label>Project title</label><input name="title" required></div><div class="field"><label>Client email</label><input name="clientEmail" type="email" required></div><div class="field"><label>Total USD</label><input name="totalAmount" type="number" min="1" required></div><div class="field"><label>Payment option</label><select name="paymentOption"><option value="half">Half payment</option><option value="full">Full payment</option></select></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field full"><button class="btn primary">Create project</button></div></form></div></div></section><section class="section" id="marketplace"><div class="panel"><div class="panel-head"><h3>Marketplace Management</h3><button class="btn" onclick="toggleUpload()">Upload product</button></div><div id="uploadBox" style="display:none;margin:14px 0"><form id="uploadForm" class="form-grid"><div class="field"><label>Product title</label><input name="title" required></div><div class="field"><label>Category</label><input name="category" value="Digital Product"></div><div class="field"><label>Current price USD</label><input name="price" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Old price USD</label><input name="oldPrice" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>WhatsApp number</label><input name="whatsappNumber"></div><div class="field"><label>Page count</label><input name="pageCount" type="number" min="0"></div><div class="field full"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Product file</label><input id="productFile" type="file" accept=".zip,.pdf,.epub,.doc,.docx,.txt" required></div><div class="field"><label>Cover image</label><input id="coverFile" type="file" accept="image/*"></div><div class="field full"><button class="btn primary">Publish product</button></div></form></div><div id="products" class="product-grid"><div class="empty">Loading live products…</div></div></div></section><section class="section" id="messages"><div class="panel"><h3>Support & Messages</h3><div id="messagesList" class="list"><div class="empty">Loading…</div></div></div></section><section class="section" id="settings"><div class="panel"><h3>Platform status</h3><div id="settingsData" class="cards"><div class="empty">Loading…</div></div></div></section></div></main></div><div class="toast" id="toast"></div><script>const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const token=localStorage.getItem('spw_user_token');const role=(JSON.parse(localStorage.getItem('spw_user')||'{}').role||'').toLowerCase();if(!token||!['admin','owner'].includes(role))location.replace('./admin.html');const api=(p,o={})=>window.SPW_APP.api(p,o);function show(id){$$('.section').forEach(x=>x.classList.toggle('active',x.id===id));$$('[data-go]').forEach(x=>x.classList.toggle('active',x.dataset.go===id));location.hash=id}$$('[data-go]').forEach(b=>b.onclick=()=>show(b.dataset.go));$('#logout').onclick=()=>{localStorage.removeItem('spw_user_token');localStorage.removeItem('spw_user');location.replace('./admin.html')};function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(x){const t=$('#toast');t.textContent=x;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}async function loadDashboard(){try{const d=await api('/api/staff/dashboard');$('#users').textContent=d.stats?.users||0;$('#jobs').textContent=d.stats?.jobs||0;$('#apps').textContent=d.stats?.applications||0;$('#withdrawals').textContent=d.stats?.pendingWithdrawals||0;$('#recentApps').innerHTML=(d.applications||[]).slice(0,8).map(a=>`<div class="list-item"><div class="grow"><strong>${esc(a.user?.fullName||a.user?.email||'Client')}</strong><small>${esc(a.job?.title||'Application')} • ${esc(a.status||'Pending')}</small></div><span class="badge">${esc(a.status||'Pending')}</span></div>`).join('')||'<div class="empty">No applications yet.</div>';$('#usersList').innerHTML=`<div class="notice">${d.stats?.users||0} client accounts are registered. Use the current backend role controls for detailed records.</div>`;$('#jobsList').innerHTML=(d.applications||[]).map(a=>`<div class="list-item"><div class="grow"><strong>${esc(a.job?.title||'Job')}</strong><small>${esc(a.user?.email||'Client')} • ${esc(a.status||'Pending')}</small></div><button class="btn" onclick="applicationAction('${a._id||a.id}')">Review</button></div>`).join('')||'<div class="empty">No application records.</div>';$('#messagesList').innerHTML=(d.messages||[]).slice(-20).map(m=>`<div class="list-item"><div class="grow"><strong>${esc(m.senderRole||'User')}</strong><small>${esc(m.message||'')}</small></div></div>`).join('')||'<div class="empty">No support messages.</div>';loadProjects();loadProducts();loadSettings()}catch(e){toast(e.message)}}async function loadProjects(){try{const d=await api('/api/projects/admin');$('#projectList').innerHTML=(d.projects||[]).map(p=>`<div class="list-item"><div class="grow"><strong>${esc(p.title)}</strong><small>${esc(p.clientEmail)} • ${esc(p.status)}</small></div><span class="badge">$${Number(p.paidAmount||0).toFixed(2)} / $${Number(p.totalAmount||0).toFixed(2)}</span></div>`).join('')||'<div class="empty">No projects.</div>'}catch(e){$('#projectList').innerHTML='<div class="empty">Project data unavailable.</div>'}}async function loadProducts(){try{const d=await api('/api/marketplace/admin/ebooks');$('#products').innerHTML=(d.ebooks||[]).map(x=>`<article class="product"><h4>${esc(x.title)}</h4><p>${esc(x.category||'Digital Product')}</p><div>${Number(x.oldPrice||0)>Number(x.price||0)?`<span class="old">$${Number(x.oldPrice).toFixed(2)}</span>`:''}<span class="price">${Number(x.price||0)<=0?'Free':'$'+Number(x.price).toFixed(2)}</span></div><div class="actions"><button class="btn" onclick="toggleProduct('${x.id}',${!x.published})">${x.published?'Hide':'Publish'}</button><button class="btn" onclick="deleteProduct('${x.id}')">Delete</button></div></article>`).join('')||'<div class="empty">No products yet.</div>'}catch(e){$('#products').innerHTML='<div class="empty">Marketplace unavailable.</div>'}}async function loadSettings(){try{const d=await api('/api/staff/platform-settings');$('#settingsData').innerHTML=Object.entries(d.integrations||{}).map(([k,v])=>`<div class="mini"><strong>${esc(k)}</strong><p class="${v?'good':'warn'}">${v?'Configured':'Not configured'}</p></div>`).join('')}catch(e){$('#settingsData').innerHTML='<div class="mini"><strong>Access</strong><p>Owner platform settings only.</p></div>'}}async function toggleProduct(id,published){try{await api('/api/marketplace/admin/ebooks/'+id,{method:'PATCH',body:JSON.stringify({published})});loadProducts()}catch(e){toast(e.message)}}async function deleteProduct(id){if(!confirm('Remove this product from the marketplace?'))return;try{await api('/api/marketplace/admin/ebooks/'+id,{method:'DELETE'});loadProducts()}catch(e){toast(e.message)}}function toggleUpload(){$('#uploadBox').style.display=$('#uploadBox').style.display==='none'?'block':'none'}async function file64(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result));r.onerror=rej;r.readAsDataURL(file)})}$('#uploadForm').onsubmit=async e=>{e.preventDefault();try{const f=$('#productFile').files[0],c=$('#coverFile').files[0],d=Object.fromEntries(new FormData(e.currentTarget).entries());if(!f)throw Error('Choose a product file.');const body={...d,price:Number(d.price||0),oldPrice:Number(d.oldPrice||0),pageCount:Number(d.pageCount||0),fileName:f.name,mimeType:f.type,fileBase64:await file64(f)};if(c){body.coverFileName=c.name;body.coverMimeType=c.type;body.coverBase64=await file64(c)}await api('/api/marketplace/admin/ebooks',{method:'POST',body:JSON.stringify(body)});e.currentTarget.reset();$('#uploadBox').style.display='none';toast('Product published.');loadProducts()}catch(err){toast(err.message)}};function showCreateProject(){$('#createProject').style.display=$('#createProject').style.display==='none'?'block':'none'}$('#projectForm').onsubmit=async e=>{e.preventDefault();try{const body=Object.fromEntries(new FormData(e.currentTarget).entries());body.totalAmount=Number(body.totalAmount);await api('/api/projects',{method:'POST',body:JSON.stringify(body)});e.currentTarget.reset();toast('Project created.');loadProjects()}catch(err){toast(err.message)}};async function applicationAction(id){try{await api('/api/staff/applications/'+id+'/status',{method:'PATCH',body:JSON.stringify({status:'Under Review'})});toast('Application moved to review.');loadDashboard()}catch(e){toast(e.message)}}loadDashboard();if(location.hash)show(location.hash.slice(1));</script></body></html>'''
